from pathlib import Path
import json,hashlib,csv
R=Path.cwd(); E=R/'evidence/06'; F=R/'followups'; sources=[]
def add(i,title,authors,year,status,url,version,pages,locators,note,repo=None,commit=None,files=None,limits=None,folder='followups/sources'):
 p=R/folder/f'{i}.pdf'; sources.append(dict(source_id='FU06-'+i,paper_id=i,title=title,authors=authors.split(';'),year=year,venue_or_status=status,primary_url=url,version=version,cutoff='2026-10-22',retrieved='2026-10-22',local_pdf=str(p.relative_to(R)),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),full_text_reviewed=True,reviewed_pdf_pages=pages,review_scope='Methods, experiments and stated limitations on listed pages; figure-only pages are not counted as visually inspected unless separately recorded.',precise_locators=locators,review=note,repo_url=repo,repo_commit=commit,code_files_inspected=files or [],code_executed=False,limitations=limits or []))
add('ua_nwm','Uncertainty-Aware World Model for Aerial Image-Goal Navigation','Deyi Zhu;Haoyu Fan;Yinan Zhu;Weichen Zhang;Shilin Ma;Xinlei Chen;Yansong Tang',2026,'arXiv preprint','https://arxiv.org/abs/2608.05597v1','v1, 6 August 2026','1-8,13-25','§3 Eqs8-15; Tables1,3; supplementary G-H',
'''AUTHOR METHOD: A frozen DINOv3 feature world model predicts action-conditioned futures. A separately trained Hierarchical Error Projection head explains residuals through multiscale low-rank subspaces; candidate goals are scored by unexplained residual energy. This is structured error scoring, not calibrated failure probability. PAPER EXPERIMENT: The matched deterministic backbone improves aerial planning; AirSim uses a20m goal tolerance and the physical pilot five tasks. Supplement G requires strong anisotropy to motivate ignoring parallel residuals; greedy projections are not a general exact global projection. INSPECTED CODE: normalized training averages patchwise ratios rather than the paper's ratio of summed energies. Optional parallel-residual weighting and same-goal wrong-action contrastive losses already exist, although disabled by default. DEDUCTION: a new decision-aligned objective must compare these controls. Construction M3 below demonstrates a possible lost task direction, not trained-model failure.''',
'https://github.com/DurYi/UA-NWM','399960ce5fea5a3aa98084beaf44d92c2def9774',['uanwm/models/hep.py:1-154','uanwm/eval/scoring.py','uanwm/train_hep.py:35-132','uanwm/losses/post_training_losses.py','configs/ua_nwm.yaml','README.md'],['No benchmark run; deployment wrappers downloaded but not deeply inspected; scene-disjoint AirGoal split not established; final qualitative figures not visually audited.'])
add('cpnav','CPNAV: Calibrated Vision-Language Navigation for Object-Goal Search in Unseen Environments','Qizhao Chen;Yuanhong Zeng;Shoh Nishino;Anushri Dixit',2026,'Preprint on official author publications page','https://practice-lab-ucla.github.io/papers/cpnav/','Author PDF retrieved22October2026','1-8','§III.E-F Eqs11-15; TableI; TablesII-III',
'''AUTHOR METHOD: Offline oracle search optimizes the minimum semantic score along a successful path; an episode-score quantile retains admissible actions for depth-first backtracking. Its stated exchangeability condition concerns complete episodes. PAPER/REPORTING: The text also describes independent observation/action calibration scenarios; the calibration unit, threshold complements and sample counts need reconciliation. Eq12 uses the .99 upper Beta quantile while claiming99% confidence, then says confidence1−δ. The visually checked formula does not support the claimed confidence interpretation (M1). Oracle-path retention alone also does not ensure budgeted success (M5). Target visibility judged manually differs from standard distance-based ObjectNav. The linked official repository was inaccessible. DEDUCTION: do not present its score threshold as a certified collision-risk controller.''',
'https://github.com/practice-lab-ucla/CPnav',None,[],['Repository not found at retrieval, not proof no code exists; no raw calibration scores; no benchmark executed.'])
add('adaptive_rollout','Adaptive Rollout Truncation Based on Epistemic Uncertainty for Efficient Offline World Model Training','Nikodem Sebastian Zymla;Laurin Thiele;Johannes Pitz',2026,'Accepted IROS2026 workshop, author-reported; not main conference','https://arxiv.org/abs/2609.21482v1','v1,18September2026','1-8','§III; TableII; Appendices C,F',
'''AUTHOR METHOD: A GRU world model with bootstrap heads or dropout truncates training rollouts when epistemic disagreement crosses a warm-up threshold, bounded between four and32 steps. PAPER EXPERIMENT: ANYmal/Ant offline prediction and rollout-compute results support efficiency in that training setting. Appendix F explicitly finds that replaying the induced horizon schedule without uncertainty gating matches within seed noise; it disclaims coverage calibration. Appendix C reports no clear downstream MOPO-PPO advantage. DEDUCTION: adaptive horizon proposals require a matched schedule replay control, and prediction efficiency is insufficient evidence for better navigation decisions. No official implementation of this new truncation method was verified; the cited predecessor repository is not substituted for it.''',limits=['No new-method source inspection; no deployment experiment reproduced.'])
add('pijepa','Policy-Guided World Model Planning for Language-Conditioned Visual Navigation','Amirhosein Chahe;Lifeng Zhou',2026,'CVPR2026 WDFM-EAI workshop, pages834-841','https://openaccess.thecvf.com/content/CVPR2026W/WDFM-EAI/papers/Chahe_Policy-Guided_World_Model_Planning_for_Language-Conditioned_Visual_Navigation_CVPRW_2026_paper.pdf','CVF workshop version','1-8','§3; §4.2; Table2; conclusion',
'''AUTHOR METHOD: Language-conditioned Octo proposals initialize MPPI; an action-conditioned JEPA scores terminal image-feature proximity. Training uses frozen image encoders and latent prediction. PAPER EXPERIMENT: CAST validation ATE/RPE are offline trajectory comparisons; proposal scoring nearly matches iterative optimization for several metrics. Closed-loop validation remains future work. INSPECTED CODE: eval_octo_mppi_cast.py670-703 explicitly takes the recorded final frame as goal. Its defaults differ from the paper's candidate/elite/temperature settings; training defaults to one-step loss and optional rollout losses detach previous predictions. No live controller is evaluated by this script. DEDUCTION: report image-goal access and reranking compute separately when transferring this mechanism to instruction-only VLN.''',
'https://github.com/AmirhoseinCh/PiJEPA','f38a265cbce4fac5aa5fd9b9f7b18c723bccb645',['scripts/eval_octo_mppi_cast.py:298-404,586-780,872-888','scripts/train_cast_wm.py:323-446','scripts/configs/train_cast_wm_config.py','README.md'],['No fetched code execution; full Octo training/data pipeline not audited; no checkpoint download.'])
add('worldmap','WorldMAP: Bootstrapping Vision-Language Navigation Trajectory Prediction with Generative World Models','Hongjin Chen;Shangyun Jiang;Tonghua Su;Chen Gao;Xinlei Chen;Yong Li;Zhibo Chen',2026,'arXiv preprint','https://arxiv.org/abs/2604.07957v1','v1,9April2026','1-9,11-12; p13 captions only','§III; TableIII; AppendixA-B',
'''AUTHOR METHOD: Generated future views, depth/pose reconstruction, language-guided segmentation and BEV/FMM planning produce teacher trajectories. A Qwen3-VL-based multihypothesis student distills these offline. PAPER EXPERIMENT: Target-Bench uses trajectories projected onto the initial image and pixel-space ADE/FDE/DTW. Pseudo-label-only ADE is95.98 versus78.34 for ground truth and42.06 combined (TableIII); gains therefore involve mixed supervision. Training-free direct VLM comparisons also change architecture and data. Appendix B's inference description invokes best-of-K without fully specifying confidence training/selection. DEDUCTION: projected path accuracy does not establish collision-free physical execution or online forecast reliability. No official code located in bounded title/author searches.''',limits=['No implementation inspection; no actual closed-loop execution evaluated in reviewed evidence; qualitative figures not visually interpreted.'])
add('janusvln','JanusVLN: Decoupling Semantics and Spatiality with Dual Implicit Memory for Vision-Language Navigation','Shuang Zeng;Dekang Qi;Xinyuan Chang;Feng Xiong;Shichao Xie;Xiaolong Wu;Shiyi Liang;Mu Xu;Xing Wei;Ning Guo',2026,'ICLR2026','https://arxiv.org/abs/2509.22548v2','v2,25February2026','1-9,17-21','§3; Tables3,5; AppendixD',
'''AUTHOR METHOD: RGB-only Qwen2.5-VL combines semantic features with frozen VGGT geometry and bounded initial/recent memory. Training includes extra ScaleVLN and DAgger trajectories. PAPER EXPERIMENT: Geometry/cache ablations support the tested architecture; Appendix D acknowledges recovery and premature stopping failures. INSPECTED CODE: VGGT caches first8/recent48 frames. Released evaluation instead resamples up to eight historical RGB images over the whole episode and calls the language model afresh; persistent semantic/LLM caches claimed in the paper were not found on that path. DEDUCTION: old observations are neither universally retained nor universally absent after48frames. Memory comparisons must specify raw-frame storage, sampling and geometric cache separately.''',
'https://github.com/MIV-XJTU/JanusVLN','8cfe3129f7af4ca276bd5e38f1fae7e5367a09ec',['src/evaluation.py:130-235,250-383','src/qwen_vl/model/modeling_qwen2_5_vl.py:1607-1691,1985-2040,2130-2156','src/qwen_vl/model/vggt/models/aggregator.py:195-297','README.md'],['No benchmark run; complete optimizer/preprocessing not audited; source path may differ from paper experiments.'])
add('humanoidvln','HumanoidVLN: A Physics-Grounded Simulator and Benchmark for Vision-Language Navigation Across Diverse Humanoid Embodiments','Quan-Dung Pham;Anh Dao;The-Anh Nguyen;Minh Nguyen-Dinh;Phuong Nam Dang;Tri Pham;Hung Tran;Bach Dao;Tuyen P. Le;Truong Nguyen;Quan Nguyen',2026,'arXiv preprint; project says Humanoids2026 under review','https://arxiv.org/abs/2608.12860v1','v1,13August2026','1-7','§III-VI; TableIII; §VI.D',
'''AUTHOR METHOD: Physics-based humanoid execution combines morphology-specific RL locomotion with PD/MPC tracking and curated large navigable scenes. All933 episodes form one zero-shot evaluation set. PAPER EXPERIMENT: Fall rates vary substantially by robot/model; action interface, tracker and locomotion policy vary together. The20-pair real/sim pilot uses one checkpoint and two scenes, explicitly not scene-level generalization. DEDUCTION: the suite makes physical failures measurable, but does not identify an architecture-only cause or solve them. Scene filtering excludes tight environments. Code/data are promised on acceptance, limiting immediate independent replication.''',
'https://humanoid-vln.github.io/',None,[],['No available code/dataset inspection; no robot execution.'])
add('reinsvln','ReInsVLN: Revisiting Historical Evidence for Training-Free Vision-and-Language Navigation','Siwei Cheng;Hao Wu;Zitong Qi;Xinming Zhang;Haoyu Xi;Peiran Yin;Haozhe Hu;Xudong Wang;Xiaoyu Shen;Wei Zhang',2026,'arXiv preprint','https://arxiv.org/abs/2610.26545v1','v1,19October2026','1-8','§III TablesI-II; §IV-V TableIV',
'''AUTHOR METHOD: ReInsBench freezes failed navigator checkpoints; deployment combines fixed-history revisits and instruction-aware visual-token compression. PAPER EXPERIMENT: R0 versus neutral reminders improves19/812 branches,2.34pp, with trajectory-cluster95% CI[-.99,5.68]. Diagnostic checkpoint/suffix construction uses reference actions; deployed fixed reminders at steps2/13 use the original instruction. Seven of11 pilot net gains already occur at initial registration. FHR also breaks78/71 previously successful Stream/Intern episodes while recovering173/126. DEDUCTION: the diagnostic does not isolate restoration of lost history from improved initial grounding; deployment efficacy and explanatory attribution are separate. Its small real-world ordinal comparison changes doorway conditions. Reuse of historical evidence alone is established prior art.''',limits=['Official implementation/supplement not found in bounded search; full eight-page paper reviewed; no experiments reproduced.'],folder='evidence/06/papers')
add('dartvln','DART-VLN: Test-Time Memory Decay and Anti-Loop Regularization for Discrete Vision-Language Navigation','Shaoheng Zhang;Zhichen Li;Guangfu Ma;Jie Mei',2026,'IEEE SMC2026 accepted, author-reported','https://arxiv.org/abs/2607.01043v4','v4,13September2026','1-6','Eqs1-5; TablesI-III; §IV.A',
'''AUTHOR METHOD: Frozen GridMM receives read-side age/repetition/novelty weighting and finite next-hop reversal/revisit penalties. PAPER EXPERIMENT: Same-checkpoint R2R/REVERIE comparisons improve several metrics; endpoint error is not uniformly improved. INSPECTED CODE: weights enter as log-priors in per-cell softmax; anti-loop penalties subtract from probabilities, with STOP unchanged. No memory-slot pruning occurs in that aggregation path. DEDUCTION: equal floored priors cancel exactly (M4), so this does not erase all stale evidence. Runtime reduction is an empirical report, not a consequence proved by reweighting alone. Finite penalties preserve the possibility of necessary backtracking but can still discourage it.''',
'https://github.com/Japluto/DART-VLN','a8889cf27723f1ffaac96ee7a802657a0b8e371a',['map_nav_src/models/vilmodel.py:740-759,817-851','map_nav_src/r2r/agent.py:452-501','map_nav_src/r2r/parser.py','README.md'],['No fetched code execution; full environment metadata update not audited.'],folder='evidence/06/papers')
add('cmmrvln','CMMR-VLN: Vision-and-Language Navigation via Continual Multimodal Memory Retrieval','Haozhou Li;Xiangyu Dong;Huiyan Jiang;Yaoming Zhou;Xiaoguang Ma',2026,'arXiv preprint','https://arxiv.org/abs/2603.07997v1','v1,9March2026','1-6','§III.A-C Eq3; TablesI-III; §IV.C',
'''AUTHOR METHOD: Viewpoint-indexed image/landmark memory retrieves prior experience as high-priority navigation rules; successful routes and first erroneous failure steps update memory. PAPER EXPERIMENT: R2R and20 physical instructions support gains under this experience-augmented protocol. However the source of first-error labels, initial memory access, episode ordering and learned attention matrix training are not sufficiently specified for a fully label-free interpretation. Ablations use a different subset from main results. DEDUCTION: outcome-aware retrieval is prior art, but changing memory/feedback contracts prevents attributing its gains purely to a retrieval mechanism. No official implementation verified in the bounded search.''',limits=['Feedback provenance and attention training unresolved; no source code inspected.'],folder='evidence/06/papers')
add('imaginenavpp','ImagineNav++: Prompting Vision-Language Models as Embodied Navigator through Scene Imagination','Teng Wang;Xinxin Zhao;Wenzhe Cai;Changyin Sun',2026,'Journal-style arXiv preprint; venue acceptance not independently verified','https://arxiv.org/abs/2512.17435v3','v3,30April2026; first version2025','1-15','§III; TablesI,III,V; §IV.J',
'''AUTHOR METHOD: A trained Where2Imagine module predicts waypoints; novel-view synthesis supplies candidate images to a frozen VLM, followed by learned VER PointNav. DINOv2-based hierarchical keyframes retain denser recent history. PAPER EXPERIMENT: TableV's full-history control does not improve success; selected history improves efficiency/quality, with an incremental approximation tradeoff. TableI distinguishes generated-future HM3D58.5/26.6 SR/SPL from oracle-real-future62.5/32.8. Author failure analysis includes hallucinated objects and ambiguous stopping. DEDUCTION: frozen high-level reasoning is not a globally untrained pipeline. The official repository contains only a coming-soon README at the inspected commit.''',
'https://github.com/200203Z/ImagineNav_plus','3803a563af97a1a0a2a6a176573a4a25c60c62a2',['README.md (release status only)'],['No executable implementation released at inspected snapshot; references16-17 not reviewed.'],folder='evidence/06/papers')
add('schrodinger_nav',"Schrodinger's Navigator: Imagining an Ensemble of Futures for Zero-Shot Object Navigation",'Yu He;Da Huang;Zhenyang Liu;Zixiao Gu;Qiang Sun;Guangnan Ye;Yanwei Fu;Yu-Gang Jiang',2026,'CoRL2026, paper and author project','https://arxiv.org/abs/2512.21201v5','v5,16October2026','1,3-9,14-20,22-23','§3-6; Tables1-3; AppendicesC-G',
'''AUTHOR METHOD: FlashWorld imagines left/right/overhead virtual views, aligns depth and combines source-tagged observed/imagined primitives into semantic/exploration/risk maps. These trajectories are complementary cameras, not independent posterior world samples. Imagined semantic cues receive a fixed discount; observations and futures remain separately stored. PAPER EXPERIMENT: Increasing imagination weight can hurt; author limitations deny formal safety guarantees. HM3D uses ShortestPathFollower. Table1's ImagineNav++ comparator equals its oracle-real-view row; protocol/version clarification is needed. Physical evidence is30 trials per condition in three rooms. DEDUCTION: source tagging, discounts and multiview imagination alone are not new; calibrated decision risk and actual low-level execution remain distinct questions.''',
'https://heyu322.github.io/Schrodinger-Navigator.github.io/',None,[],['No official executable code located; videos not reviewed; qualitative image-only pages not inspected.'],folder='evidence/06/papers')
add('memoir','Dream to Recall: Imagination-Guided Experience Retrieval for Memory-Persistent Vision-and-Language Navigation','Yunzhe Xu;Yiyuan Pan;Zhe Liu',2026,'TPAMI accepted15March2026 per official repository','https://arxiv.org/abs/2510.08553v2','v2,30March2026; first version2025','1,3-13,17-21','Algorithms1-3; TablesII,V; §V.E; supplementIV.A',
'''AUTHOR METHOD: A language-conditioned world model queries separate observation/behavior memories; DUET gains a history encoder and three-way action fusion. Persistent graphs permit inter-episode retrieval. PAPER EXPERIMENT: TableV controls instruction/state/random/full retrieval; oracle retrieval remains much stronger. §V.E identifies similar-goal confusion, premature imagination and equal treatment of failed/successful history. Continuous transfer improves success but loses path fidelity versus episodic DUET. INSPECTED CODE: history matching ranks cumulative compatibility products rather than the described prefix-minimum criterion; inference termination threshold differs from the supplement. Teacher paths in the inspected retrieval helper only calculate diagnostics. DEDUCTION: generic future-guided retrieval is established, and confidence-aware retrieval is explicitly suggested future work; a new proposal needs a sharper mechanism/test.''',
'https://github.com/xyz9911/Memoir','ea7fb9066366eb2aff3eabbc87b227a567cc6b90',['utils/graph_utils.py:419-531','nav_src/iter_nav/agent_ir2r.py:998-1082','vlnbert/vilmodel.py:1171-1248','nav_src/iter_nav/parser.py','readme.md'],['No code execution; full training/loss pipeline not audited; cited theorem derivations not independently certified.'],folder='evidence/06/papers')
add('neubay','Long-Horizon Model-Based Offline Reinforcement Learning Without Explicit Conservatism','Tianwei Ni;Esther Derman;Vineet Jain;Vincent Taboga;Siamak Ravanbakhsh;Pierre-Luc Bacon',2026,'ICML2026 PMLR306:92875-92924','https://proceedings.mlr.press/v306/ni26a.html','Published proceedings','1-9 main paper only','§4 Algorithms1-2; §5; Eq4',
'''AUTHOR METHOD: A history-dependent Bayesian offline-RL policy learns across an ensemble of dynamics models; rollouts stop using in-dataset uncertainty quantiles. Long horizons reduce bootstrap reliance while layer normalization controls predicted increments. PAPER EXPERIMENT: D4RL/NeoRL studies support dataset-dependent benefits; parameters are tuned using true-environment performance and narrow-coverage tasks remain difficult. DEDUCTION: uncertainty-triggered rollout truncation and history-based adaptation are established beyond VLN. Eq4 bounds prediction magnitudes, not closeness to the true trajectory by itself. No probability-calibration or instruction-following guarantee follows. This is a scoped main-paper comparison, not a review of its extensive supplementary proofs or implementation.''',
'https://github.com/twni2016/neubay',None,[],['Full supplement pp10-50 and implementation not reviewed; no reproduction.'],folder='evidence/06/papers')
(E/'sources.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2),encoding='utf-8')
lines=['# Assignment06 follow-up source cards','', 'Cutoff:22October2026. Evidence labels distinguish author reports, inspected source and original deductions. Bibliography, exact PDF scopes, hashes, commits and limitations are in [sources.json](sources.json). No project code or navigation benchmark was executed.','']
for x in sources:
 lines += [f"## {x['source_id']}: {x['title']}",'',f"{'; '.join(x['authors'])}. {x['venue_or_status']}. [{x['version']}]({x['primary_url']}). PDF pages reviewed: {x['reviewed_pdf_pages']}.",'',x['review'],'',f"Locators: {x['precise_locators']}.",'', 'Limitations: '+' '.join(x['limitations']),'']
(E/'source_cards.md').write_text('\n'.join(lines),encoding='utf-8')
print('Saved',len(sources),'source records; maximum card review words',max(len(x['review'].split()) for x in sources))
